const r = await tools.exec_command({cmd:"$refs = @(
  @{ Repo = 'actions/checkout'; Tag = 'v4' },
  @{ Repo = 'actions/setup-node'; Tag = 'v4' },
  @{ Repo = 'actions/checkout'; Tag = 'v6' },
  @{ Repo = 'docker/setup-buildx-action'; Tag = 'v3' },
  @{ Repo = 'docker/build-push-action'; Tag = 'v6' },
  @{ Repo = 'docker/login-action'; Tag = 'v3' },
  @{ Repo = 'docker/metadata-action'; Tag = 'v5' }
)
foreach ($ref in $refs) {
  $obj = gh api "repos/$($ref.Repo)/git/ref/tags/$($ref.Tag)" | ConvertFrom-Json
  $type = $obj.object.type
  $sha = $obj.object.sha
  while ($type -eq 'tag') {
    $tagObj = gh api "repos/$($ref.Repo)/git/tags/$sha" | ConvertFrom-Json
    $type = $tagObj.object.type
    $sha = $tagObj.object.sha
  }
  if ($type -ne 'commit' -or $sha -notmatch '^[0-9a-f]{40}$') { throw "Could not resolve $($ref.Repo)@$($ref.Tag) to a commit" }
  '{0}@{1} {2}' -f $ref.Repo, $ref.Tag, $sha
}","workdir":"C:\Code\Projects\APP-StackMap","yield_time_ms":30000,"max_output_tokens":10000});
text(r.output);
